//! php-src's syntax check, reproduced exactly.
//!
//! goro's [`crate::Parser`] is a hand-written recursive-descent parser; its
//! idea of which programs are syntactically valid, and the wording of its
//! errors, can only approximate the bison LALR(1) parser of php-src. This
//! module runs bison's own automaton for `Zend/zend_language_parser.y`
//! (tables in [`crate::php_grammar`], generated by
//! `tools/gen_php_grammar.py`) over the parser-mode token stream of
//! [`crate::php_scanner`], so that the first syntax error -- including
//! bison's `expecting ...` list after default reductions and
//! `zend_yytnamerr()`'s token descriptions -- and the line it is reported on
//! are those of php-src. The scanner's bracket nesting checks
//! (`Unclosed '{'`, `Unmatched ')'`) are performed too.
//!
//! It is a pure recognizer: no semantic actions run, so the handful of
//! errors php-src raises from parser actions are handled specially
//! (`__HALT_COMPILER()` stops scanning, `<?=` used as an identifier) or left
//! to goro's parser (modifier errors).

use crate::php_grammar as g;
use crate::php_scanner::{self as ps, ScanToken};

/// A syntax error as php-src reports it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SyntaxError {
    pub message: String,
    pub line: u32,
    /// Byte offset of the offending token.
    pub offset: usize,
}

/// php_scanner token id (php-src's token kind value) -> bison symbol.
#[inline]
fn symbol(id: i32) -> i32 {
    if (0..=g::YYMAXUTOK).contains(&id) {
        g::YYTRANSLATE[id as usize] as i32
    } else {
        2 // YYSYMBOL_YYUNDEF
    }
}

const YYSYMBOL_EOF: i32 = 0;
const YYSYMBOL_ERROR: i32 = 1;

/// One parser-mode token: bison symbol + source range.
#[derive(Clone, Copy)]
struct PTok {
    sym: i32,
    /// php_scanner token id
    id: i32,
    start: usize,
    end: usize,
    line: u32,
}

/// Check `src` the way php-src's compiler would; `skip_shebang` mirrors
/// CG(skip_shebang).
pub fn check(src: &[u8], short_tags: bool, skip_shebang: bool) -> Option<SyntaxError> {
    run(src, short_tags, skip_shebang).error
}

/// The outcome of a parse.
#[derive(Debug, Default)]
pub struct Recognized {
    pub error: Option<SyntaxError>,
    /// Start offsets of the keyword tokens the parser turned into T_STRING
    /// (zend_lex_tstring()'s ON_FEEDBACK events).
    pub feedback: Vec<usize>,
    /// Where `__halt_compiler();` stopped the scanner (offset, line).
    pub stop: Option<(usize, u32)>,
}

/// Run php-src's parser over `src`.
pub fn run(src: &[u8], short_tags: bool, skip_shebang: bool) -> Recognized {
    let mut out = Recognized::default();
    out.error = parse(
        src,
        short_tags,
        skip_shebang,
        &mut out.feedback,
        &mut out.stop,
    );
    out
}

fn parse(
    src: &[u8],
    short_tags: bool,
    skip_shebang: bool,
    feedback: &mut Vec<usize>,
    stop: &mut Option<(usize, u32)>,
) -> Option<SyntaxError> {
    let mut sc = ps::Scanner::new(src, short_tags, skip_shebang);
    let mut nest: Vec<(u8, u32)> = Vec::new();
    let mut stopped = false;
    // Current CG(zend_lineno) as the scanner sees it after the last token.
    let mut last_line = 1u32;
    let mut pending_newline = false;

    // Fetch the next parser-mode token, applying the scanner's nesting
    // checks (which raise a ParseError and end parsing).
    let mut next = |stopped: bool,
                    last_line: &mut u32,
                    pending_newline: &mut bool|
     -> Result<PTok, SyntaxError> {
        if *pending_newline {
            *last_line += 1;
            *pending_newline = false;
        }
        loop {
            let t: Option<ScanToken> = if stopped { None } else { sc.next_token() };
            let Some(t) = t else {
                // RETURN_END_TOKEN: check_nesting_at_end()
                let eof_line = *last_line;
                if let Some(&(open, oline)) = nest.last() {
                    return Err(SyntaxError {
                        message: bad_nesting(open, oline, eof_line, 0),
                        line: eof_line,
                        offset: src.len(),
                    });
                }
                return Ok(PTok {
                    sym: YYSYMBOL_EOF,
                    id: 0,
                    start: src.len(),
                    end: src.len(),
                    line: eof_line,
                });
            };
            let text = &src[t.start..t.end];
            let mut close_tag = false;
            let sym = match t.id {
                ps::T_OPEN_TAG | ps::T_WHITESPACE | ps::T_COMMENT | ps::T_DOC_COMMENT => {
                    *last_line = t.line + token_newlines(&t, text);
                    continue;
                }
                ps::T_CLOSE_TAG => {
                    close_tag = true;
                    g::YYTRANSLATE[b';' as usize] as i32
                }
                ps::T_OPEN_TAG_WITH_ECHO => symbol(ps::T_ECHO),
                id => symbol(id),
            };
            // Line after scanning this token (HANDLE_NEWLINES); `?>\n`
            // defers its newline to the next token fetch.
            let mut line = t.line + token_newlines(&t, text);
            if close_tag && text.last() == Some(&b'\n') {
                line -= 1;
                *pending_newline = true;
            }
            *last_line = line;
            let id = t.id;
            if t.scripting && (id == b'(' as i32 || id == b'[' as i32 || id == b'{' as i32) {
                nest.push((id as u8, line));
            } else if matches!(id, ps::T_CURLY_OPEN | ps::T_DOLLAR_OPEN_CURLY_BRACES) {
                nest.push((b'{', line));
            } else if id == ps::T_ATTRIBUTE {
                nest.push((b'[', line));
            } else if t.scripting && (id == b')' as i32 || id == b']' as i32 || id == b'}' as i32) {
                let closing = id as u8;
                match nest.last() {
                    None => {
                        return Err(SyntaxError {
                            message: format!("Unmatched '{}'", closing as char),
                            line,
                            offset: t.start,
                        });
                    }
                    Some(&(open, oline)) => {
                        let ok =
                            matches!((open, closing), (b'{', b'}') | (b'[', b']') | (b'(', b')'));
                        if !ok {
                            return Err(SyntaxError {
                                message: bad_nesting(open, oline, line, closing),
                                line,
                                offset: t.start,
                            });
                        }
                        nest.pop();
                    }
                }
            }
            return Ok(PTok {
                sym,
                id: t.id,
                start: t.start,
                end: t.end,
                line,
            });
        }
    };

    // The bison skeleton (yacc.c), without semantic actions. Each stack
    // entry holds its state and the index in `toks` of its first token
    // (u32::MAX: none).
    let mut stack: Vec<(i32, u32)> = Vec::with_capacity(256);
    stack.push((0, u32::MAX));
    let mut toks: Vec<PTok> = Vec::with_capacity(src.len() / 8 + 16);
    // The lookahead: its index in `toks` and its symbol (NO_LA: none).
    const NO_LA: u32 = u32::MAX;
    let mut la: u32 = NO_LA;
    let mut la_sym: i32 = 0;
    let mut state: i32 = 0;
    'parse: loop {
        if state == g::YYFINAL {
            return None;
        }
        let mut yyn = g::YYPACT[state as usize] as i32;
        'act: {
            if yyn != g::YYPACT_NINF {
                if la == NO_LA {
                    match next(stopped, &mut last_line, &mut pending_newline) {
                        Ok(t) => {
                            la_sym = t.sym;
                            la = toks.len() as u32;
                            toks.push(t);
                        }
                        Err(e) => return Some(e),
                    }
                }
                yyn += la_sym;
                if (0..=g::YYLAST).contains(&yyn) && g::YYCHECK[yyn as usize] as i32 == la_sym {
                    yyn = g::YYTABLE[yyn as usize] as i32;
                    if yyn > 0 {
                        // shift
                        state = yyn;
                        stack.push((state, la));
                        la = NO_LA;
                        continue 'parse;
                    }
                    if yyn == g::YYTABLE_NINF {
                        return Some(syntax_error(src, &toks[la as usize], state));
                    }
                    yyn = -yyn;
                    // reduce below
                    break 'act;
                }
            }
            yyn = g::YYDEFACT[state as usize] as i32;
            if yyn == 0 {
                if la == NO_LA {
                    // A consistent error state without lookahead
                    // cannot happen in this grammar; report generically.
                    return Some(SyntaxError {
                        message: "syntax error".into(),
                        line: last_line,
                        offset: src.len(),
                    });
                }
                return Some(syntax_error(src, &toks[la as usize], state));
            }
        }
        // reduce by rule yyn
        let len = g::YYR2[yyn as usize] as usize;
        let base = stack.len() - len;
        let first_val = if len > 0 { stack[base].1 } else { u32::MAX };
        if SPECIAL_RULE[yyn as usize] {
            let val = |k: usize| stack[base + k].1 as usize;
            match yyn {
                g::RULE_TOP_HALT_COMPILER => {
                    // zend_stop_lexing()
                    stopped = true;
                    let end = toks[val(3)].end;
                    *stop = Some((end, last_line));
                }
                // zend_throw_exception(): a compile error, not a syntax error;
                // goro's parser reports it.
                g::RULE_INNER_HALT_COMPILER => return None,
                g::RULE_IDENTIFIER_SEMI_RESERVED
                | g::RULE_CLASS_CONST_SEMI_RESERVED
                | g::RULE_FUNCTION_NAME_READONLY
                | g::RULE_CALL_READONLY
                | g::RULE_TRAIT_ALIAS_RESERVED => {
                    let v = if yyn == g::RULE_TRAIT_ALIAS_RESERVED {
                        val(2)
                    } else {
                        first_val as usize
                    };
                    if let Some(e) = lex_tstring(src, &toks, v, last_line) {
                        return Some(e);
                    }
                    if let Some(t) = toks.get(v) {
                        feedback.push(t.start);
                    }
                }
                _ => {
                    let first_val = first_val as usize;
                    let (first, last) = match yyn {
                        g::RULE_TRAIT_ALIAS_MODIFIER_NAME | g::RULE_TRAIT_ALIAS_MODIFIER => {
                            (val(2), val(2))
                        }
                        g::RULE_CLASS_MODIFIERS_ADD | g::RULE_ANON_CLASS_MODIFIERS_ADD => {
                            (first_val, val(1))
                        }
                        _ => {
                            // non_empty_member_modifiers: consecutive tokens
                            let mut last = first_val;
                            while toks.get(last + 1).is_some_and(|t| is_member_modifier(t.id)) {
                                last += 1;
                            }
                            (first_val, last)
                        }
                    };
                    let ids: Vec<i32> = (first..=last)
                        .filter_map(|i| toks.get(i))
                        .map(|t| t.id)
                        .collect();
                    if let Some(message) = modifier_error(yyn, &ids) {
                        return Some(SyntaxError {
                            message,
                            line: last_line,
                            offset: toks.get(first).map_or(0, |t| t.start),
                        });
                    }
                }
            }
        }
        stack.truncate(base);
        let top = stack[base - 1].0;
        let lhs = g::YYR1[yyn as usize] as i32 - g::YYNTOKENS;
        let yyi = g::YYPGOTO[lhs as usize] as i32 + top;
        state = if (0..=g::YYLAST).contains(&yyi) && g::YYCHECK[yyi as usize] as i32 == top {
            g::YYTABLE[yyi as usize] as i32
        } else {
            g::YYDEFGOTO[lhs as usize] as i32
        };
        stack.push((state, first_val));
    }
}

/// The rules whose reduction does something here (see parse()).
static SPECIAL_RULE: [bool; g::YYR2.len()] = {
    let mut t = [false; g::YYR2.len()];
    let rules = [
        g::RULE_TOP_HALT_COMPILER,
        g::RULE_INNER_HALT_COMPILER,
        g::RULE_IDENTIFIER_SEMI_RESERVED,
        g::RULE_CLASS_CONST_SEMI_RESERVED,
        g::RULE_FUNCTION_NAME_READONLY,
        g::RULE_CALL_READONLY,
        g::RULE_TRAIT_ALIAS_RESERVED,
        g::RULE_CLASS_MODIFIERS_ADD,
        g::RULE_ANON_CLASS_MODIFIERS_ONE,
        g::RULE_ANON_CLASS_MODIFIERS_ADD,
        g::RULE_CPP_MODIFIERS,
        g::RULE_PROPERTY_MODIFIERS,
        g::RULE_METHOD_MODIFIERS,
        g::RULE_CONST_MODIFIERS,
        g::RULE_HOOK_MODIFIERS,
        g::RULE_TRAIT_ALIAS_MODIFIER_NAME,
        g::RULE_TRAIT_ALIAS_MODIFIER,
    ];
    let mut i = 0;
    while i < rules.len() {
        t[rules[i] as usize] = true;
        i += 1;
    }
    t
};

fn is_member_modifier(id: i32) -> bool {
    matches!(
        id,
        ps::T_PUBLIC
            | ps::T_PROTECTED
            | ps::T_PRIVATE
            | ps::T_PUBLIC_SET
            | ps::T_PROTECTED_SET
            | ps::T_PRIVATE_SET
            | ps::T_STATIC
            | ps::T_ABSTRACT
            | ps::T_FINAL
            | ps::T_READONLY
    )
}

/// The compile error php-src's parser actions raise for a modifier list
/// (zend_add_class_modifier(), zend_add_anonymous_class_modifier(),
/// zend_modifier_list_to_flags(), zend_modifier_token_to_flag()).
fn modifier_error(rule: i32, ids: &[i32]) -> Option<String> {
    const PUBLIC: u32 = 1;
    const PROTECTED: u32 = 2;
    const PRIVATE: u32 = 4;
    const PPP: u32 = PUBLIC | PROTECTED | PRIVATE;
    const STATIC: u32 = 0x10;
    const FINAL: u32 = 0x20;
    const ABSTRACT: u32 = 0x40;
    const READONLY: u32 = 0x80;
    const PUBLIC_SET: u32 = 0x100;
    const PROTECTED_SET: u32 = 0x200;
    const PRIVATE_SET: u32 = 0x400;
    const PPP_SET: u32 = PUBLIC_SET | PROTECTED_SET | PRIVATE_SET;
    let name = |id: i32| match id {
        ps::T_PUBLIC => "public",
        ps::T_PROTECTED => "protected",
        ps::T_PRIVATE => "private",
        ps::T_STATIC => "static",
        ps::T_FINAL => "final",
        ps::T_READONLY => "readonly",
        ps::T_ABSTRACT => "abstract",
        ps::T_PUBLIC_SET => "public(set)",
        ps::T_PROTECTED_SET => "protected(set)",
        _ => "private(set)",
    };
    match rule {
        g::RULE_CLASS_MODIFIERS_ADD
        | g::RULE_ANON_CLASS_MODIFIERS_ONE
        | g::RULE_ANON_CLASS_MODIFIERS_ADD => {
            let anon = rule != g::RULE_CLASS_MODIFIERS_ADD;
            let class_flag = |id: i32| match id {
                ps::T_ABSTRACT => ABSTRACT,
                ps::T_FINAL => FINAL,
                _ => READONLY,
            };
            let mut flags = 0u32;
            for (i, &id) in ids.iter().enumerate() {
                let new = class_flag(id);
                if !anon && i == 0 {
                    flags = new;
                    continue;
                }
                let nf = flags | new;
                if anon {
                    if new & ABSTRACT != 0 {
                        return Some(
                            "Cannot use the abstract modifier on an anonymous class".into(),
                        );
                    }
                    if new & FINAL != 0 {
                        return Some("Cannot use the final modifier on an anonymous class".into());
                    }
                    if flags & new & READONLY != 0 {
                        return Some("Multiple readonly modifiers are not allowed".into());
                    }
                } else {
                    if flags & new & ABSTRACT != 0 {
                        return Some("Multiple abstract modifiers are not allowed".into());
                    }
                    if flags & new & FINAL != 0 {
                        return Some("Multiple final modifiers are not allowed".into());
                    }
                    if flags & new & READONLY != 0 {
                        return Some("Multiple readonly modifiers are not allowed".into());
                    }
                    if nf & ABSTRACT != 0 && nf & FINAL != 0 {
                        return Some("Cannot use the final modifier on an abstract class".into());
                    }
                }
                flags = nf;
            }
            None
        }
        _ => {
            #[derive(PartialEq, Clone, Copy)]
            enum T {
                Property,
                Method,
                Constant,
                Cpp,
                Hook,
            }
            let target = match rule {
                g::RULE_CPP_MODIFIERS => T::Cpp,
                g::RULE_PROPERTY_MODIFIERS => T::Property,
                g::RULE_CONST_MODIFIERS => T::Constant,
                g::RULE_HOOK_MODIFIERS => T::Hook,
                _ => T::Method,
            };
            let to_flag = |id: i32| -> Result<u32, String> {
                let f = match id {
                    ps::T_PUBLIC if target != T::Hook => PUBLIC,
                    ps::T_PROTECTED if target != T::Hook => PROTECTED,
                    ps::T_PRIVATE if target != T::Hook => PRIVATE,
                    ps::T_READONLY if matches!(target, T::Property | T::Cpp) => READONLY,
                    ps::T_ABSTRACT if matches!(target, T::Method | T::Property) => ABSTRACT,
                    ps::T_FINAL => FINAL,
                    ps::T_STATIC if matches!(target, T::Property | T::Method) => STATIC,
                    ps::T_PUBLIC_SET if matches!(target, T::Property | T::Cpp) => PUBLIC_SET,
                    ps::T_PROTECTED_SET if matches!(target, T::Property | T::Cpp) => PROTECTED_SET,
                    ps::T_PRIVATE_SET if matches!(target, T::Property | T::Cpp) => PRIVATE_SET,
                    _ => 0,
                };
                if f != 0 {
                    return Ok(f);
                }
                let member = match target {
                    T::Property => "property",
                    T::Method => "method",
                    T::Constant => "class constant",
                    T::Cpp => "parameter",
                    T::Hook => "property hook",
                };
                Err(format!(
                    "Cannot use the {} modifier on a {}",
                    name(id),
                    member
                ))
            };
            if matches!(
                rule,
                g::RULE_TRAIT_ALIAS_MODIFIER_NAME | g::RULE_TRAIT_ALIAS_MODIFIER
            ) {
                return ids.first().and_then(|&id| to_flag(id).err());
            }
            let mut flags = 0u32;
            for &id in ids {
                let new = match to_flag(id) {
                    Ok(f) => f,
                    Err(e) => return Some(e),
                };
                let duplicate = flags & new != 0;
                // zend_add_member_modifier()
                let nf = flags | new;
                if flags & PPP != 0 && new & PPP != 0 {
                    return Some("Multiple access type modifiers are not allowed".into());
                }
                if nf & ABSTRACT != 0 && nf & FINAL != 0 {
                    if target == T::Method {
                        return Some("Cannot use the final modifier on an abstract method".into());
                    }
                    if target == T::Property {
                        return Some(
                            "Cannot use the final modifier on an abstract property".into(),
                        );
                    }
                }
                if matches!(target, T::Property | T::Cpp)
                    && flags & PPP_SET != 0
                    && new & PPP_SET != 0
                {
                    return Some("Multiple access type modifiers are not allowed".into());
                }
                if duplicate {
                    return Some(format!("Multiple {} modifiers are not allowed", name(id)));
                }
                flags = nf;
            }
            None
        }
    }
}

/// zend_lex_tstring(): `<?=` (lexed as T_ECHO) cannot become an identifier.
fn lex_tstring(src: &[u8], toks: &[PTok], idx: usize, line: u32) -> Option<SyntaxError> {
    let t = toks.get(idx)?;
    if src[t.start..t.end].starts_with(b"<?=") {
        return Some(SyntaxError {
            message: "Cannot use \"<?=\" as an identifier".into(),
            line,
            offset: t.start,
        });
    }
    None
}

/// newlines() of a token's text (the scanner counted its "\n").
#[inline]
fn token_newlines(t: &ScanToken, text: &[u8]) -> u32 {
    if t.has_cr { newlines(text) } else { t.newlines }
}

fn newlines(text: &[u8]) -> u32 {
    // HANDLE_NEWLINES: "\n", "\r\n" and a bare "\r" each count once.
    // (without a "\r", the count of "\n": a loop the compiler vectorizes)
    let (mut lf, mut cr) = (0u32, 0u32);
    for &c in text {
        lf += u32::from(c == b'\n');
        cr += u32::from(c == b'\r');
    }
    if cr == 0 {
        return lf;
    }
    let mut n = 0;
    let mut i = 0;
    while i < text.len() {
        match text[i] {
            b'\n' => n += 1,
            b'\r' => {
                n += 1;
                if text.get(i + 1) == Some(&b'\n') {
                    i += 1;
                }
            }
            _ => {}
        }
        i += 1;
    }
    n
}

fn bad_nesting(opening: u8, opening_line: u32, line: u32, closing: u8) -> String {
    let mut s = format!("Unclosed '{}'", opening as char);
    if opening_line != line {
        s.push_str(&format!(" on line {}", opening_line));
    }
    if closing != 0 {
        s.push_str(&format!(" does not match '{}'", closing as char));
    }
    s
}

/// yysyntax_error() with zend_yytnamerr().
fn syntax_error(src: &[u8], tok: &PTok, state: i32) -> SyntaxError {
    let mut args: Vec<i32> = vec![tok.sym];
    // yypcontext_expected_tokens()
    let yyn = g::YYPACT[state as usize] as i32;
    if yyn != g::YYPACT_NINF {
        let xbegin = if yyn < 0 { -yyn } else { 0 };
        let checklim = g::YYLAST - yyn + 1;
        let xend = checklim.min(g::YYNTOKENS);
        let mut expected = Vec::new();
        let mut too_many = false;
        for x in xbegin..xend {
            if g::YYCHECK[(x + yyn) as usize] as i32 == x
                && x != YYSYMBOL_ERROR
                && g::YYTABLE[(x + yyn) as usize] as i32 != g::YYTABLE_NINF
            {
                if expected.len() == 4 {
                    too_many = true;
                    break;
                }
                expected.push(x);
            }
        }
        if !too_many {
            args.extend(expected);
        }
    }
    let mut msg = String::from("syntax error, unexpected ");
    msg.push_str(&describe_unexpected(src, tok));
    for (i, &a) in args.iter().enumerate().skip(1) {
        msg.push_str(if i == 1 { ", expecting " } else { " or " });
        msg.push_str(&describe_expected(g::YYTNAME[a as usize]));
    }
    SyntaxError {
        message: msg,
        line: tok.line,
        offset: tok.start,
    }
}

/// zend_yytnamerr() for the unexpected token.
fn describe_unexpected(src: &[u8], tok: &PTok) -> String {
    let toktype_full = g::YYTNAME[tok.sym as usize];
    let content = &src[tok.start..tok.end];
    if tok.sym == YYSYMBOL_EOF {
        return "end of file".into();
    }
    if toktype_full == "\"'\\\\'\"" {
        return "token \"\\\"".into();
    }
    if toktype_full == "\"amp\"" {
        return "token \"&\"".into();
    }
    if toktype_full == "'\"'" {
        return "double-quote mark".into();
    }
    let mut toktype = toktype_full;
    if toktype.len() >= 2 && toktype.starts_with('"') {
        toktype = &toktype[1..toktype.len() - 1];
    }
    if toktype.starts_with('\'') {
        return format!("token \"{}\"", &toktype[1..toktype.len() - 1]);
    }
    let mut c = content;
    if c.len() == 1 && toktype_full == "\"invalid character\"" {
        return format!("character 0x{:02X}", c[0]);
    }
    if let Some(nl) = c.iter().position(|&b| b == b'\n') {
        c = &c[..nl];
    }
    let mut toktype = toktype.to_string();
    if !c.is_empty() && toktype_full == "\"quoted string\"" {
        if c[0] == b'"' {
            toktype = "double-quoted string".into();
        } else if c[0] == b'\'' {
            toktype = "single-quoted string".into();
        }
    }
    if !c.is_empty() && (c[0] == b'\'' || c[0] == b'"') {
        c = &c[1..];
    }
    if !c.is_empty() && (c[c.len() - 1] == b'\'' || c[c.len() - 1] == b'"') {
        c = &c[..c.len() - 1];
    }
    if c.len() > 30 + 3 {
        format!("{} \"{}...\"", toktype, String::from_utf8_lossy(&c[..30]))
    } else {
        format!("{} \"{}\"", toktype, String::from_utf8_lossy(c))
    }
}

/// zend_yytnamerr() for an expected token.
fn describe_expected(toktype: &str) -> String {
    if toktype == "\"'\\\\'\"" {
        return "\"\\\"".into();
    }
    if toktype == "\"amp\"" {
        return "token \"&\"".into();
    }
    let mut t = toktype;
    if t.len() >= 2 && t.starts_with('"') {
        t = &t[1..t.len() - 1];
    }
    t.replace('\'', "\"")
}

/// One token_get_all() / PhpToken::tokenize() token: (id, start, end, line);
/// ids below 256 are single characters.
pub type RawToken = (i32, usize, usize, u32);

/// The token stream of token_get_all() / PhpToken::tokenize(). With
/// `parse` (TOKEN_PARSE) the code is parsed too: keywords the parser used
/// as identifiers become T_STRING, `__halt_compiler();` ends the stream
/// with the rest as T_INLINE_HTML, and errors are returned (ParseError);
/// the scanner's diagnostics are left in take_lexer_deprecations() /
/// take_lexer_warnings().
pub fn tokenize(src: &[u8], parse: bool) -> Result<Vec<RawToken>, SyntaxError> {
    let short_tags = crate::short_open_tag();
    let mut out: Vec<RawToken> = Vec::new();
    let mut sc = ps::Scanner::new(src, short_tags, false);
    if !parse {
        // tokenize(): the scanner alone; after T_HALT_COMPILER the next
        // three meaningful tokens are kept and the rest is inline HTML.
        let mut need_tokens: i32 = -1;
        while let Some(t) = sc.next_token() {
            out.push((t.id, t.start, t.end, t.line));
            if need_tokens != -1 {
                if !matches!(
                    t.id,
                    ps::T_WHITESPACE | ps::T_OPEN_TAG | ps::T_COMMENT | ps::T_DOC_COMMENT
                ) {
                    need_tokens -= 1;
                    if need_tokens == 0 {
                        if t.end < src.len() {
                            out.push((ps::T_INLINE_HTML, t.end, src.len(), t.line));
                        }
                        break;
                    }
                }
            } else if t.id == ps::T_HALT_COMPILER {
                need_tokens = 3;
            }
        }
        return Ok(out);
    }
    let r = run(src, short_tags, false);
    // Errors goro's own lexer detects while scanning (invalid numeric
    // literals, bad escapes) are raised by php-src's scanner too.
    // Its deprecations / warnings are left for the caller to emit.
    let _ = crate::take_lexer_error();
    let _ = crate::take_lexer_deprecations();
    let _ = crate::take_lexer_warnings();
    let _ = crate::Lexer::new(src).tokenize();
    if let Some((message, line)) = crate::take_lexer_error() {
        if !message.starts_with("syntax error") && r.error.as_ref().is_none_or(|e| line <= e.line) {
            return Err(SyntaxError {
                message,
                line,
                offset: 0,
            });
        }
    }
    if let Some(e) = r.error {
        return Err(e);
    }
    let mut feedback = r.feedback;
    feedback.sort_unstable();
    let limit = r.stop.map_or(src.len(), |(o, _)| o);
    while let Some(t) = sc.next_token() {
        if t.start >= limit {
            break;
        }
        let id = if feedback.binary_search(&t.start).is_ok() {
            ps::T_STRING
        } else {
            t.id
        };
        out.push((id, t.start, t.end, t.line));
    }
    if let Some((o, line)) = r.stop {
        if o < src.len() {
            out.push((ps::T_INLINE_HTML, o, src.len(), line));
        }
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    fn msg(src: &str) -> Option<(String, u32)> {
        super::check(src.as_bytes(), false, false).map(|e| (e.message, e.line))
    }

    #[test]
    fn valid_code() {
        assert_eq!(
            msg(r"<?php namespace A\B; use C\{D, function e}; echo \strlen('x');"),
            None
        );
        assert_eq!(
            msg("<?php class A { const FOREACH = 1; function list() {} }"),
            None
        );
        assert_eq!(
            msg(r#"<?php echo "$a[1] {$b->c} ${d}"; __halt_compiler(); }}}"#),
            None
        );
    }

    #[test]
    fn syntax_errors() {
        assert_eq!(
            msg("<?php $a = [1, FOREACH];"),
            Some((
                r#"syntax error, unexpected token "foreach", expecting "]""#.into(),
                1
            ))
        );
        assert_eq!(
            msg("<?php\nfunction f() {\n  const X = 1;\n}"),
            Some((r#"syntax error, unexpected token "const""#.into(), 3))
        );
        assert_eq!(
            msg(r"<?php echo Foo \ Bar;"),
            Some((
                r#"syntax error, unexpected token "\", expecting "," or ";""#.into(),
                1
            ))
        );
        assert_eq!(
            msg("<?php\n{\n"),
            Some(("Unclosed '{' on line 2".into(), 3))
        );
        assert_eq!(msg("<?php )"), Some(("Unmatched ')'".into(), 1)));
        assert_eq!(
            msg("<?php class A { use T { x as y?><?= as z; } }"),
            Some((r#"Cannot use "<?=" as an identifier"#.into(), 1))
        );
    }
}
